class Timer {
  constructor() {
    this.elapsed = 0;
    this._start = null;
  }

  start() {
    this._start = performance.now();
    return this;
  }

  stop() {
    this.elapsed = (performance.now() - this._start) / 1000;
  }
}

class TransactionManager {
  constructor(data) {
    this._data = data;
    this._backup = null;
  }

  begin() {
    this._backup = [...this._data];
    return this._data;
  }

  commit() {
    this._backup = null;
  }

  rollback() {
    this._data.length = 0;
    this._data.push(...this._backup);
    this._backup = null;
  }
}
